INSERT INTO `xhs_note_comment` VALUES (2001, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059740595, 1781059740595, '67c1acca0000000016015f9e', 1740745930000, '679858bb000000001800adf6', '是的', 0, '\"\"', '67bab9be00000000190169bc', '0');
INSERT INTO `xhs_note_comment` VALUES (2002, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059745770, 1781059745770, '68726b65000000000400a19e', 1752329061000, '679858bb000000001800adf6', '不是，我这款琴比较老了，内录的话要自己接声卡，比较麻烦[笑哭R]', 0, '\"\"', '6872599a000000000401531d', '0');
INSERT INTO `xhs_note_comment` VALUES (2003, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059752102, 1781059752102, '680b0a420000000004014253', 1745553986000, '679858bb000000001800adf6', '这首曲子我刚开始学几个月左右就会弹了，现在我又完善了一下，可以看看我置顶的那条视频，那是我去年弹的，我是零基础自学的，但不是成人[笑哭R][笑哭R]，现在高一[偷笑R]', 0, '\"\"', '6809eab30000000012003e75', '1');
INSERT INTO `xhs_note_comment` VALUES (2004, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059760835, 1781059760835, '67a318ad0000000012034936', 1738741933000, '679858bb000000001800adf6', '这首我也没有什么办法，我也是一遍一遍练的，因为右手没有太多的技巧性，只是需要手指灵活度，可以单独多练练右手，练到完全不用看都能弹的程度就行了[偷笑R][偷笑R]但可能过程比较漫长，你可以翻下我最底下那个作品，那是我去年弹的，看看能不能找到共同问题', 0, '\"\"', '67a317de000000000a01b913', '1');
INSERT INTO `xhs_note_comment` VALUES (2005, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059769337, 1781059769337, '67a09fb8000000001b03a47f', 1738579897000, '679858bb000000001800adf6', '谢谢', 0, '\"\"', '67a09ef0000000001b03b064', '0');
INSERT INTO `xhs_note_comment` VALUES (2006, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059769372, 1781059769372, '68561d9c000000002002eece', 1750474141000, '679858bb000000001800adf6', '外录的，环境安静一点就能录清晰了，像我这种老款电钢外录的话要声卡转接，挺麻烦的[笑哭R]', 0, '\"\"', '682303ab00000000080246a8', '0');
INSERT INTO `xhs_note_comment` VALUES (2007, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059769399, 1781059769399, '6803dec30000000004016ea8', 1745084100000, '679858bb000000001800adf6', '跟fp18比的话应该是这个更好，罗兰最好选fp30x', 0, '\"\"', '6803cb70000000000401790c', '0');
INSERT INTO `xhs_note_comment` VALUES (2008, '6469f4070000000029017fd0', 'Augenstern', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bv39tb80m0g5p39ug3qavugho2f2mg?imageView2/2/w/120/format/jpg', NULL, 1781059769430, 1781059769430, '67b8732800000000160179f6', 1740141353000, '679858bb000000001800adf6', '私你[害羞R]', 0, '\"\"', '67b5e30f000000001c005bf8', '1');
