INSERT INTO `xhs_note_comment` VALUES (2010, '5b8b8a0f4ebf7f00018d4077', '成人零基础👇学钢琴', 'https://sns-avatar-qc.xhscdn.com/avatar/5b8d39f38b30b000016999c2.jpg?imageView2/2/w/120/format/jpg', NULL, 1781059772549, 1781059772549, '69423c3f000000001d025ac6', 1765948479000, '693fc7ce000000001b023dd6', '其实这波双十一和双十二，罗兰30x降价幅度真的挺大。不过，新手确实更合适225一些👍120手感会比225好点。售后的话……我两台雅马哈修了一年多才订到配件，所以雅马哈的琴基本不用考虑维修，喜欢就买就可以了[捂脸R]', 11, '\"\"', '0', '0');
INSERT INTO `xhs_note_comment` VALUES (2011, '62e7573d000000001501ff0a', '木木（一切都是最好的安排版）', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo318hcg2p9jq6g5on7asulbvoanumgcr8?imageView2/2/w/120/format/jpg', NULL, 1781059772606, 1781059772606, '694093a70000000039005847', 1765839784000, '693fc7ce000000001b023dd6', '我也，本来预算只有2500，后来硬是拿下了p225', 9, '\"\"', '0', '5');
