INSERT INTO `xhs_note_comment` VALUES (2327, '65af375f000000001001f7b4', '若菲', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31cqrpcmmgc005pdf6tfk3ttk66k2ea8?imageView2/2/w/120/format/jpg', NULL, 1781086740415, 1781086740415, '6918542600000000390298be', 1763202087000, '66e90f970000000012011e00', '请问用M3 16G编流行或者古风歌曲大概编多少轨可以保持流畅，50轨可以吗？还是说50-70轨建议32G？请问24G的话50-70轨带的动嘛，谢谢', 0, '\"\"', '66fe8b4e000000000d00fe27', '0');
INSERT INTO `xhs_note_comment` VALUES (2328, '58f4e20082ec397dcf8acf84', 'kyy', 'https://sns-avatar-qc.xhscdn.com/avatar/5f0ad7d7625ab80001137b92.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086740447, 1781086740447, '69e46be0000000001401a017', 1776577505000, '66e90f970000000012011e00', '这次的不行[doge]我新买的m5，喇叭应该一样的，我觉得的不行', 0, '\"\"', '66ffa12e000000000f00e0ef', '0');
