INSERT INTO `xhs_note_comment` VALUES (2330, '5b3cfe1fe8ac2b4bd7e41610', 'Baileys', 'https://sns-avatar-qc.xhscdn.com/avatar/615b1f58f4ebff327de2f348.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086743126, 1781086743126, '66ec18a600000000240075c8', 1726748839000, '66e90f970000000012011e00', '是的，我看他自己作音乐那房间都大家伙，显示屏都超大的两个', 0, '\"\"', '66ebbae500000000200214f6', '11');
INSERT INTO `xhs_note_comment` VALUES (2331, '6194f2da000000001000fd28', '深圳第一甜妹', 'https://sns-avatar-qc.xhscdn.com/avatar/6194f2da000000001000fd28.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086743181, 1781086743181, '6833564c000000000d0144cf', 1748194893000, '66e90f970000000012011e00', '显示屏是那些东西里面花钱最节省的了[笑哭R]一个音响几万一个耳机几千一排吉他贝斯十几万都很常见[笑哭R][笑哭R]', 0, '\"\"', '66ec18a600000000240075c8', '9');
INSERT INTO `xhs_note_comment` VALUES (2332, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086745226, 1781086745226, '690c10b300000000390297ad', 1762398390000, '66e90f970000000012011e00', '需要如图去官网下载声卡驱动的。', 0, '\"http://sns-web-i10.rednotecdn.com/202606101818/a46a67d1484bffaf46336ea86034ff6c/comment/1040g2h031ohf92vckq005otsr809i887cdu13p8!nd_whgt34_webp_wm_1?src=A\"', '690c0a930000000037012213', '0');
INSERT INTO `xhs_note_comment` VALUES (2333, '6123625f0000000001009f38', '胡格纳兹宁', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u5klleg2a205o93c9fg97poq5o7ij8?imageView2/2/w/120/format/jpg', NULL, 1781086745784, 1781086745784, '690c20270000000033027b71', 1762402343000, '66e90f970000000012011e00', '是下载好的 最开始是连接上的突然就不行了 试了很多办法也没有解决 已经去声卡店里和拓展坞店排除了这两个的问题 现在可能只剩下是电脑的原因了', 0, '\"\"', '690c10b300000000390297ad', '0');
INSERT INTO `xhs_note_comment` VALUES (2334, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086745826, 1781086745826, '690c21990000000039024563', 1762402714000, '66e90f970000000012011e00', '可以再试试跳过扩展坞，声卡直连MacBook，或者给扩展坞为充电预留的type-c连上充电，看看是不是供电问题，再不行就找Arturia的售后问问吧。', 0, '\"\"', '690c20270000000033027b71', '0');
INSERT INTO `xhs_note_comment` VALUES (2335, '6123625f0000000001009f38', '胡格纳兹宁', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u5klleg2a205o93c9fg97poq5o7ij8?imageView2/2/w/120/format/jpg', NULL, 1781086745858, 1781086745858, '690c27290000000037024be2', 1762404138000, '66e90f970000000012011e00', '谢谢！', 0, '\"\"', '690c21990000000039024563', '0');
INSERT INTO `xhs_note_comment` VALUES (2336, '6123625f0000000001009f38', '胡格纳兹宁', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u5klleg2a205o93c9fg97poq5o7ij8?imageView2/2/w/120/format/jpg', NULL, 1781086745887, 1781086745887, '690d69aa0000000037024dc5', 1762486698000, '66e90f970000000012011e00', '不好意思再打扰一下🙏试过给拓展坞供电了 不插电脑声卡可以正常接受麦克风得输入信号并且耳机可以接听，但是接了电脑输入就又会断掉，请问这大概率是声卡的问题还是拓展坞的问题？', 0, '\"\"', '690c21990000000039024563', '0');
INSERT INTO `xhs_note_comment` VALUES (2337, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086745922, 1781086745922, '690d70f000000000390282c7', 1762488561000, '66e90f970000000012011e00', '如果声卡直连电脑正常，加拓展坞不能用，那么就是拓展坞的问题，我不清楚你使用宿主的情况和熟悉程度，通常在宿主的设置里也可以看一下，是否显示外置声卡驱动（因为可能默认内置声卡），如果宿主的设置里有识别外置声卡驱动，并且可以显示延迟是多少毫秒，大概率没什么问题，如果宿主根本就没有识别外置声卡驱动，那可能是连接的某个环节出了问题，因为我并不清楚你的具体操作细节，能给到的帮助只有这些，你可以自己探索一下。', 0, '\"\"', '690d69aa0000000037024dc5', '0');
INSERT INTO `xhs_note_comment` VALUES (2338, '6123625f0000000001009f38', '胡格纳兹宁', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u5klleg2a205o93c9fg97poq5o7ij8?imageView2/2/w/120/format/jpg', NULL, 1781086748406, 1781086748406, '690d71c40000000033004d41', 1762488773000, '66e90f970000000012011e00', '好的！感谢🙏', 0, '\"\"', '690d70f000000000390282c7', '0');
INSERT INTO `xhs_note_comment` VALUES (2339, '5d358ad6000000001102b929', '。？', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31tp4at6sn2005n9lhbb4de99u59otto?imageView2/2/w/120/format/jpg', NULL, 1781086750436, 1781086750436, '66eb9ed6000000000b020226', 1726717655000, '66e90f970000000012011e00', '反正m3不卡[笑哭R]', 0, '\"\"', '66ea533400000000240065e0', '1');
INSERT INTO `xhs_note_comment` VALUES (2340, '5ee0785e0000000001002d4b', '超级大鲁蛇', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31ga553om2k005nn0f1f08babfeamgoo?imageView2/2/w/120/format/jpg', NULL, 1781086750973, 1781086750973, '66eba321000000002400aec2', 1726718753000, '66e90f970000000012011e00', '那有没有上32g色的必要 如果是macbook pro', 0, '\"\"', '66eb9ed6000000000b020226', '0');
INSERT INTO `xhs_note_comment` VALUES (2341, '5d358ad6000000001102b929', '。？', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31tp4at6sn2005n9lhbb4de99u59otto?imageView2/2/w/120/format/jpg', NULL, 1781086751013, 1781086751013, '66ebab320000000004032013', 1726720818000, '66e90f970000000012011e00', '如果资金充足上32也没问题，我24的平时是够用了', 0, '\"\"', '66eba321000000002400aec2', '0');
INSERT INTO `xhs_note_comment` VALUES (2342, '5ee0785e0000000001002d4b', '超级大鲁蛇', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31ga553om2k005nn0f1f08babfeamgoo?imageView2/2/w/120/format/jpg', NULL, 1781086751047, 1781086751047, '66f3b7f00000000024011a91', 1727248368000, '66e90f970000000012011e00', 'm3 32g 给干到2w人民币了 实在看不起', 0, '\"\"', '66ebab320000000004032013', '0');
INSERT INTO `xhs_note_comment` VALUES (2343, '65c23366000000000903cc22', '光年温度', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31keot3cc326g5pe26dj2fj124iurdm8?imageView2/2/w/120/format/jpg', NULL, 1781086751085, 1781086751085, '67605c2700000000120099ed', 1734368295000, '66e90f970000000012011e00', '有，写弦乐的话建议内存怼顶配', 0, '\"\"', '66eba321000000002400aec2', '0');
INSERT INTO `xhs_note_comment` VALUES (2344, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086753134, 1781086753134, '66f7afe3000000000d01e5d2', 1727508451000, '66e90f970000000012011e00', 'Midi是usb线，可以直接连扩展坞usb口，不需要声卡，声卡的作用主要是连接麦克风和内录乐器，还有就是减少使用编曲软件录音的延迟。', 0, '\"\"', '66f7ab8000000000040332a0', '20');
INSERT INTO `xhs_note_comment` VALUES (2345, '64b90a710000000014037e29', 'Littlestar💫', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f8f2a34639eb26eb1cd.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086753791, 1781086753791, '66f7f870000000000c01606b', 1727527025000, '66e90f970000000012011e00', '啊，原来如此，谢谢[皱眉R][皱眉R]', 0, '\"\"', '66f7afe3000000000d01e5d2', '0');
INSERT INTO `xhs_note_comment` VALUES (2346, '5fd57a91000000000100677e', 'hi', 'https://sns-avatar-qc.xhscdn.com/avatar/5fd57a91000000000100677e.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086753834, 1781086753834, '66f95cde000000000f0075bd', 1727618271000, '66e90f970000000012011e00', '朋友朋友，你得意思是用有外放的键盘对吗？我最近也在研究 这个声卡 这个麦 是必须的嘛？[笑哭R]', 0, '\"\"', '66f7ab8000000000040332a0', '0');
INSERT INTO `xhs_note_comment` VALUES (2347, '5fd57a91000000000100677e', 'hi', 'https://sns-avatar-qc.xhscdn.com/avatar/5fd57a91000000000100677e.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086753866, 1781086753866, '66f95d4e000000000f004f63', 1727618382000, '66e90f970000000012011e00', '麦克风 应该是满足要唱歌的收音吧，不然只弹琴的话 midi线连接电脑和外放键盘就好了好像', 0, '\"\"', '66f95cde000000000f0075bd', '0');
INSERT INTO `xhs_note_comment` VALUES (2348, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086753896, 1781086753896, '66f96057000000000d01f05e', 1727619160000, '66e90f970000000012011e00', 'Midi线连接电脑后，宿主有音源，可以直接把midi信号转化为声音，选择你需要的音源就可以直接录制，不需要再外放键盘；如果你是合成器键盘，键盘自带音色，输出音频，就需要连大二芯到声卡，取决于你到底是使用midi信号（不带音色）还是音频输出；当然也可以直接外录，但我没有使用笔记本电脑的内置声卡和自带麦克风外录过，你可以试试，我一般用电容麦连声卡外录，个人经验仅供参考。', 0, '\"\"', '66f95d4e000000000f004f63', '2');
INSERT INTO `xhs_note_comment` VALUES (2349, '5fd57a91000000000100677e', 'hi', 'https://sns-avatar-qc.xhscdn.com/avatar/5fd57a91000000000100677e.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086753928, 1781086753928, '66f960bf000000000f00e1ae', 1727619264000, '66e90f970000000012011e00', '[得意R]哇 好详细好贴心 谢谢贴主大大', 0, '\"\"', '66f96057000000000d01f05e', '0');
INSERT INTO `xhs_note_comment` VALUES (2350, '64b90a710000000014037e29', 'Littlestar💫', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f8f2a34639eb26eb1cd.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086756519, 1781086756519, '66f966b90000000002007144', 1727620794000, '66e90f970000000012011e00', '不是的不是的[笑哭R]我一开始是在想，苹果电脑是不是好像可以不需要声卡的[笑哭R]所以问了帖主这个问题哈哈[笑哭R]', 0, '\"\"', '66f95cde000000000f0075bd', '0');
INSERT INTO `xhs_note_comment` VALUES (2351, '5fd57a91000000000100677e', 'hi', 'https://sns-avatar-qc.xhscdn.com/avatar/5fd57a91000000000100677e.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086756561, 1781086756561, '66f966ff0000000020027721', 1727620863000, '66e90f970000000012011e00', '笔记本都自带，楼下贴主大大说了很详细的介绍。', 0, '\"\"', '66f966b90000000002007144', '0');
INSERT INTO `xhs_note_comment` VALUES (2352, '64b90a710000000014037e29', 'Littlestar💫', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f8f2a34639eb26eb1cd.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086756598, 1781086756598, '66f968ef000000000c017893', 1727621359000, '66e90f970000000012011e00', '看到了，谢谢[哭惹R]', 0, '\"\"', '66f966ff0000000020027721', '0');
INSERT INTO `xhs_note_comment` VALUES (2353, '5b0058dde8ac2b62428962be', '蓝丝绒', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31mgad0nnks0g4a5fjncdqolu9ctfa78?imageView2/2/w/120/format/jpg', NULL, 1781086756636, 1781086756636, '6708a68400000000160337ed', 1728620165000, '66e90f970000000012011e00', '如果不用内录乐器和麦克风纯用DAW做纯音乐的话就用不上声卡了对嘛', 0, '\"\"', '66f7afe3000000000d01e5d2', '0');
INSERT INTO `xhs_note_comment` VALUES (2354, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086756670, 1781086756670, '6708b2d3000000001000459a', 1728623316000, '66e90f970000000012011e00', '是的，这种情况如果内置声卡带得动的话，延迟不影响编曲，直接用midi也行。', 0, '\"\"', '6708a68400000000160337ed', '1');
INSERT INTO `xhs_note_comment` VALUES (2355, '5d3ee94f000000001202745d', 'Biscuit 琳', 'https://sns-avatar-qc.xhscdn.com/avatar/617ff949a977e198ddf66d9d.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086759158, 1781086759158, '675eb17f0000000011000e97', 1734259072000, '66e90f970000000012011e00', '声卡录人声和内录乐器   显示的是两条音轨吗  还是合并在一起了?', 0, '\"\"', '66f7afe3000000000d01e5d2', '0');
INSERT INTO `xhs_note_comment` VALUES (2356, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086761206, 1781086761206, '68f598fe000000003901f217', 1760925951000, '66e90f970000000012011e00', '拓展坞是可以供电的，是因为有的声卡、硬盘或其他设备可能需要额外的供电，只连电脑带不动，这个你可以参考个人的使用情况，比如你的设备如果通过Mac供电很稳定，那么你就不需要再给扩展坞插额外供电。', 0, '\"\"', '68f5964400000000370252cf', '1');
INSERT INTO `xhs_note_comment` VALUES (2357, '678d1d7f000000000e010f7d', '钻石心', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31svjroo762005psd3lvji3rtamvtimo?imageView2/2/w/120/format/jpg', NULL, 1781086762024, 1781086762024, '68f59c980000000033024623', 1760926904000, '66e90f970000000012011e00', '就是说这个拓展坞上的设备，需要供电，所以要在上面插typec，我图上这样的话，拓展坞上的设备没有供电源', 0, '\"http://sns-web-i10.rednotecdn.com/202606101819/5b1921cc81f4ebada8b40e215caa3267/comment/1040g2h031nrhjhgfmg005psd3lvji3rt03ct758!nd_whgt34_webp_wm_1?src=A\"', '68f598fe000000003901f217', '0');
INSERT INTO `xhs_note_comment` VALUES (2358, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086762063, 1781086762063, '68f59eca00000000390261ca', 1760927435000, '66e90f970000000012011e00', '拓展坞连接Mac后本身是供电加传输，这你不用担心，拓展坞上有额外供电接口，你可以理解为备用，当电脑连接的供电电压不够，才需要，所以你可以用你的方案先尝试，遇到问题再解决。', 0, '\"\"', '68f59c980000000033024623', '1');
INSERT INTO `xhs_note_comment` VALUES (2359, '678d1d7f000000000e010f7d', '钻石心', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31svjroo762005psd3lvji3rtamvtimo?imageView2/2/w/120/format/jpg', NULL, 1781086762103, 1781086762103, '68f59f5e000000003300cb05', 1760927583000, '66e90f970000000012011e00', '好的谢谢哥', 0, '\"\"', '68f59eca00000000390261ca', '0');
INSERT INTO `xhs_note_comment` VALUES (2360, '62122a39000000001000ba9c', '....net', 'https://sns-avatar-qc.xhscdn.com/avatar/62122a39000000001000ba9c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086762137, 1781086762137, '6915a46e000000003300e2a5', 1763026031000, '66e90f970000000012011e00', '我的mac接拓展坞上然后连键盘  能识别到键盘 但是键盘的电源灯不亮 我给拓展坞插电源也不行 是不是线的问题 换成那种PD对应的线吗[哭惹R]', 0, '\"\"', '68f59eca00000000390261ca', '0');
INSERT INTO `xhs_note_comment` VALUES (2361, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086762168, 1781086762168, '6915ab950000000039020ed4', 1763027861000, '66e90f970000000012011e00', '有这种可能吧，我的第一个midi键盘因为它有内置声卡驱动，用扩展坞带不动，需要直连电脑（不过那时我用的还不是Mac）。而大多数midi键盘只是提供按键时产生的midi信号，一般不用拓展坞单独充电，也不排除你的拓展坞插口分流的电压不够，可以考虑一下跳过拓展坞直连Mac试试，用个usb转type-c的转接头。', 0, '\"\"', '6915a46e000000003300e2a5', '1');
INSERT INTO `xhs_note_comment` VALUES (2362, '62122a39000000001000ba9c', '....net', 'https://sns-avatar-qc.xhscdn.com/avatar/62122a39000000001000ba9c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086764760, 1781086764760, '6915c430000000003300cf9e', 1763034160000, '66e90f970000000012011e00', '试过了 还是没有电 只能识别到 没有电源 看来还是得单独给拓展坞供电[哭惹R]', 0, '\"\"', '6915ab950000000039020ed4', '0');
INSERT INTO `xhs_note_comment` VALUES (2363, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086766818, 1781086766818, '6837d664000000000d0159b3', 1748489829000, '66e90f970000000012011e00', '16GB', 0, '\"\"', '6837c693000000000d014388', '1');
INSERT INTO `xhs_note_comment` VALUES (2364, '5b06f3104eacab6898b1a9a6', 'Y I N G', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30o4gerh9i8004a5kf2ph1ad6ccio6e0?imageView2/2/w/120/format/jpg', NULL, 1781086767333, 1781086767333, '683848700000000007034988', 1748519024000, '66e90f970000000012011e00', '是256还是512呢', 0, '\"\"', '6837d664000000000d0159b3', '1');
INSERT INTO `xhs_note_comment` VALUES (2365, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086767408, 1781086767408, '68384ebb000000000b017f2f', 1748520636000, '66e90f970000000012011e00', '内存16GB 硬盘512GB 只是个人选择', 0, '\"\"', '683848700000000007034988', '2');
INSERT INTO `xhs_note_comment` VALUES (2366, '5b06f3104eacab6898b1a9a6', 'Y I N G', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30o4gerh9i8004a5kf2ph1ad6ccio6e0?imageView2/2/w/120/format/jpg', NULL, 1781086767439, 1781086767439, '68394b980000000007036dfe', 1748585369000, '66e90f970000000012011e00', '用logic还算顺畅吗？我也想和你一样配置', 0, '\"\"', '68384ebb000000000b017f2f', '0');
INSERT INTO `xhs_note_comment` VALUES (2367, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086767474, 1781086767474, '68394cde00000000090153b4', 1748585695000, '66e90f970000000012011e00', '我个人觉得没任何问题，比起我用另一台windows的cubase要顺畅许多。', 0, '\"\"', '68394b980000000007036dfe', '1');
INSERT INTO `xhs_note_comment` VALUES (2368, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086769518, 1781086769518, '6760dd470000000011001bc8', 1734401351000, '66e90f970000000012011e00', '是的', 0, '\"\"', '67607686000000000d038ff9', '0');
INSERT INTO `xhs_note_comment` VALUES (2369, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0?imageView2/2/w/120/format/jpg', NULL, 1781086769559, 1781086769559, '672158be000000001a01a78a', 1730238655000, '66e90f970000000012011e00', '声卡连接扩展坞的，扩展坞本身就有type C接口可以充电，MacBook air有两个type C，扩展坞占一个，另一个空着的也可以充电，不影响声卡使用。声卡录音需要48V，所以理论上扩展坞需要一直连着充电，不然带动声卡会消耗MacBook的电池。', 0, '\"\"', '6721096a000000001702cf5c', '3');
INSERT INTO `xhs_note_comment` VALUES (2370, '66405ec400000000030302c5', '樂先生（雾屿）', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3204497i82q6g5pi0br20u0m5v99rgu0?imageView2/2/w/120/format/jpg', NULL, 1781086770104, 1781086770104, '672417a7000000001702f589', 1730418600000, '66e90f970000000012011e00', '感谢回复，因为我出现一个问题，我的KPS综合效果器自带声卡，并连接MacBook，在不充电的情况下库乐队录音使用正常，但凡一插充电器声卡就卡顿，有杂音或者找不到KPS的声卡', 0, '\"\"', '672158be000000001a01a78a', '0');
