INSERT INTO `xhs_note_comment` VALUES (2412, '5ccba60e000000001200d37b', '在灿烂阳光下', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31md5ipm2507g5n6bko74hkrrh49ogdg?imageView2/2/w/120/format/jpg', NULL, 1781086796548, 1781086796548, '69ab4c120000000004002737', 1772833811000, '69a27c7a000000001d027bab', '我之前在家练古筝，被邻居找过三回了，有一次还是下午3点半左右，也就练40分钟左右吧，白天也有人找，说孩子在睡觉，从此我的古筝就荒废了，快忘干净了，我怕再被找，但是我练钢琴从来没被人找过，可能古筝的声音比较响吧，我用的电钢琴，声音可以调节可能会好点儿', 0, '\"\"', '69a677740000000015014cf7', '1');
