INSERT INTO `xhs_note_comment` VALUES (2421, '65c644a9000000000903d494', 'Luuuuuuumi', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u17mekmmu005pe68ikifl4kphjglkg?imageView2/2/w/120/format/jpg', NULL, 1781086801872, 1781086801872, '69c2823e000000000f01d153', 1774355007000, '69a27c7a000000001d027bab', '这种艺术工作者，而且还经常练的，通常都是买很贵的房子，普通人根本买不起[尬住R]而且就算买便宜的，楼上楼下大爷大妈小孩都吵，建议努努力买别墅哈', 0, '\"\"', '69a3e8dd000000000b035f8f', '0');
