INSERT INTO `xhs_note_comment` VALUES (2427, '5a4ee6b14eacab44c18ff24d', 'forgot_forever', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30v7qg85hlg004a0lqajb3sids310010?imageView2/2/w/120/format/jpg', NULL, 1781086804637, 1781086804637, '69c1f16f000000001500476f', 1774317936000, '69a27c7a000000001d027bab', '可拉倒吧，一练琴练几个小时，周围邻居都被迫听着你稀巴烂的琴，怎么不算扰民。除非是隔音好的小区或者大房间邻居听不到的那种，否则在公寓或者老旧小区练乐器不做额外隔音措施的一律归为素质低。', 0, '\"\"', '69a677740000000015014cf7', '2');
