INSERT INTO `xhs_note_comment` VALUES (2455, '65345cea000000000301c2c1', '嘿卡皮', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31sbsnqfel60g5p9kbjl0rgm149niq8o?imageView2/2/w/120/format/jpg', NULL, 1781086823387, 1781086823387, '69aa1f4f0000000005033877', 1772756815000, '69a27c7a000000001d027bab', '快告诉我怎么做的！！！我被楼上噪音弄疯了！！', 0, '\"\"', '69a3c02e0000000018022d01', '0');
INSERT INTO `xhs_note_comment` VALUES (2456, '67b7f72a000000000d009769', '财摄兼收', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31o8dt5rnl8005ptnusl395r9ead6pp8?imageView2/2/w/120/format/jpg', NULL, 1781086823416, 1781086823416, '69aa2fff0000000014032cf0', 1772761088000, '69a27c7a000000001d027bab', '首先，你得有个钢琴，然后你得有恒心练习，最后，隔音差的是上下楼，隔壁隔音好的才行。综合上述，我的情况你那不一定适用，还是买个橡皮锤敲敲吧[失望R]', 0, '\"\"', '69aa1f4f0000000005033877', '0');
