INSERT INTO `xhs_note_comment` VALUES (2539, '60d485480000000020028c04', '沈洛熹💛', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31fpai5a7nq005o6kgl485304dp7qono?imageView2/2/w/120/format/jpg', '浙江', 1781086877146, 1781087167842, '6a23bd0500000000290242b6', 1780727045000, '68ad4ebe000000001c03cd66', '小姐姐我想问一下放小熊的那个地方，深度（宽度）是多少，我查了数据只有一个长度145。我想买个盖的蕾丝但是我的琴还没到，预定中，但是又想提前买装饰物[笑哭R]能不能方便的时候量一下给我', 2, '\"\"', '0', '0');
INSERT INTO `xhs_note_comment` VALUES (2540, '5abefaa7e8ac2b56d70c0501', '红帽小外婆', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31u2fldk57q604a44h3tae181hc4ifr0?imageView2/2/w/120/format/jpg', '广东', 1781086877176, 1781087167869, '6a18dd62000000002b025e21', 1780014435000, '68ad4ebe000000001c03cd66', '求助：我买了新电钢，我踩着延音踏板，按下琴键。手指不离开琴键，脚离开延音踏板。琴键的声音还会有。客服说正常[石化R]但是我之前的琴是不会这样的。', 4, '\"\"', '0', '1');
