INSERT INTO `xhs_note_comment` VALUES (2542, '684a9477000000001b0192e3', 'zoro', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31pslbcq35a005q2aihrmr4n3ijse6oo?imageView2/2/w/120/format/jpg', NULL, 1781086877241, 1781087167934, '68b6a1570000000030031acf', 1756799321000, '68ad4ebe000000001c03cd66', '本来也是买电钢的，弹到后面才发现电钢的局限行，特别是弹古典无法控制音色，最后又买了台立式[笑哭R]', 2, '\"http://sns-web-i10.rednotecdn.com/202606101821/45f20af25a405d583efcaffd62cab474/comment/1040g2h031lu1e33t5i705q2aihrmr4n39741a50!nd_whlt34_webp_wm_1?src=A\"', '0', '1');
