INSERT INTO `xhs_note_comment` VALUES (2673, '5dbaab2b0000000001005999', '钢琴老林师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31kclr7qij0605ndqlclg8mcp5fg76ng?imageView2/2/w/120/format/jpg', NULL, 1781086951592, 1781089270810, '67471f90000000000200758b', 1732714385000, '6746d860000000000703b9a0', '坐多了容易驼背，一驼背重心会靠后，重心靠后容易手腕下压，手腕下压容易瘪指，一瘪指音色一天世界[doge]', 38, '\"\"', '0', '983');
