INSERT INTO `xhs_note_comment` VALUES (2676, '591c6f106a6a695110b50fba', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31g7i28hd1k7049gk74nh03tqr1kvcig?imageView2/2/w/120/format/jpg', NULL, 1781086951687, 1781089270918, '67483202000000000200558a', 1732784643000, '6746d860000000000703b9a0', '因为坐多了腿就要架上来了[萌萌哒R](bushi)', 11, '\"\"', '0', '405');
