INSERT INTO `xhs_note_comment` VALUES (2678, '5a980a11e8ac2b33acbb1ad8', '有妖气的双子座', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31ropbv4032k04a308v5126molmrio7g?imageView2/2/w/120/format/jpg', NULL, 1781086951748, 1781089271015, '697a255300000000050391c0', 1769612628000, '6746d860000000000703b9a0', '5K以下罗兰FP18也可以，手感重是因为罗兰的琴纵比较接近真钢', 4, '\"\"', '0', '0');
INSERT INTO `xhs_note_comment` VALUES (2679, '64a25c3c000000000a020e03', '疯狂小路路_0.0', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31vmjurtc2a005p52bgu2k3g3agancm0?imageView2/2/w/120/format/jpg', NULL, 1781086951775, 1781089270949, '674717bb0000000002005c74', 1732712379000, '6746d860000000000703b9a0', '你可以多试一下，如果做很多的话谈起来很别扭的', 6, '\"\"', '0', '38');
INSERT INTO `xhs_note_comment` VALUES (2680, '63a7a93b0000000027028ed5', '杨世文pianist', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v3cnp7njm005ot7l4tpt3mlr9r5c6g?imageView2/2/w/120/format/jpg', NULL, 1781086951804, 1781087217088, '67484aaf000000003d01c9b0', 1732790959000, '6746d860000000000703b9a0', '坐多少是个人习惯，坐多一点弹着舒服那就坐多一点，只坐一点点或三分之一这个说法我个人其实不太理解，重心都不稳 手臂咋动啊？其他乐器要站着玩就是因为身体重心垂直向地面，弹钢琴能重心垂直接触地面的只有凳子腿，干嘛不用啊，只坐一点点下盘真的稳吗', 1, '\"\"', '0', '6');
INSERT INTO `xhs_note_comment` VALUES (2681, '6031447000000000010022e7', 'Sgvessey Elsia', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31boi5am10k6g5o1h8ho088n71v4h3pg?imageView2/2/w/120/format/jpg', NULL, 1781086951832, 1781089270982, '676d75f4000000000d03aadd', 1735226868000, '6746d860000000000703b9a0', '我跷二郎腿，咋舒服咋来[猪头R]', 6, '\"\"', '0', '2');
