INSERT INTO `xhs_note_comment` VALUES (2683, '61cabd7c000000001000e702', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31mslu1p9mm505oeanlu41po2b56v9so?imageView2/2/w/120/format/jpg', NULL, 1781086953903, 1781089273078, '67472b750000000002007273', 1732717429000, '6746d860000000000703b9a0', '所以我手腕疼是因为坐太后了吗[哭惹R]', 0, '\"\"', '67471f90000000000200758b', '77');
