INSERT INTO `xhs_note_comment` VALUES (2766, '59d744146eea885bd7784596', '糖炒李子', 'https://sns-avatar-qc.xhscdn.com/avatar/6267a2ff0c3bebf2deee90c6.jpg?imageView2/2/w/120/format/jpg', NULL, 1781086999402, 1781087240105, '674867e70000000007017ef4', 1732798439000, '6746d860000000000703b9a0', '感觉高的人，腿长的人，坐多少都无所谓。我可能比较矮或者说腿短，又喜欢凳子高一些，觉得会比较好活动，所以坐大概三分之一，脚踩实，也更好发力。再一个，凳子坐多了就容易驼背。', 0, '\"\"', '67484aaf000000003d01c9b0', '0');
INSERT INTO `xhs_note_comment` VALUES (2767, '60faf84d000000000100a096', 'Kyle', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31btdr7230k6g5o7qv16g984m0cblddo?imageView2/2/w/120/format/jpg', NULL, 1781086999438, 1781089290067, '676da598000000001200b9cf', 1735239065000, '6746d860000000000703b9a0', '那就证明你不会[笑哭R]要不然就是只会一点[笑哭R]当你真正开始提速的时候[笑哭R]正常的动作会让你的手部更好发力（除非你已经精通，或者这首曲子练了不上不下半年[笑哭R]）', 0, '\"\"', '676d75f4000000000d03aadd', '0');
