INSERT INTO `xhs_note_comment` VALUES (2942, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087798640, 1781087798640, '68ce68ee0000000030011789', 1758357743000, '68ca7a060000000012017da4', '我们从幼儿园中班到现在学了8年考到10级，这些书里有三本没学过。一路觉得挺辛苦，是院校老师一对一教的，学期每天练琴至少2小时，假期考前每天3-4小时。累并快乐着！', 13, '\"\"', '0', '7');
INSERT INTO `xhs_note_comment` VALUES (2943, '5edc2db4000000000100033f', '我就是那个压舱石', 'https://sns-avatar-qc.xhscdn.com/avatar/63d5167672e641d79eaaf43c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087798681, 1781087798681, '68cbb0ab000000002301f4fd', 1758179499000, '68ca7a060000000012017da4', '我成人学，目标3级已经是天花板了', 10, '\"\"', '0', '6');
