INSERT INTO `xhs_note_comment` VALUES (2946, '6707b445000000001d02155f', 'tonight', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31f2s21m6midg5po7mh2nc5av73b71f0?imageView2/2/w/120/format/jpg', NULL, 1781087798790, 1781087798790, '68d6a243000000001a030e7a', 1758896708000, '68ca7a060000000012017da4', '娃三岁半开始学琴，四岁时一对一，第一年每天15-20分钟，第二年每天30-40分钟，5岁半五级良好，第三年到第五平时每天练琴40分钟左右，考级前两个月，每天练琴1小时，七岁半考7级，八岁半考八级，十岁那年平时每天练琴一小时左右，周末到老师家练琴1-2小时，十岁半考10级。', 4, '\"\"', '0', '10');
