INSERT INTO `xhs_note_comment` VALUES (2962, '57236ad150c4b430e8131025', '快乐小林', 'https://sns-avatar-qc.xhscdn.com/avatar/6211202ee68ecc3f8773bd9a.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087807181, 1781087807181, '68e8eb4d0000000039030e49', 1760095053000, '68ca7a060000000012017da4', '三岁半每天一小时（上课半小时，家里练半小时）四岁半开始每天80分钟左右（上课半小时，在家分两次练50分钟）现在五岁半每天100分钟（上课40分钟，在家分两次练60分钟）接下来在家练琴时间要加长到90分钟！（目前三级，纯粹提高孩子修养不考键盘专业）', 0, '\"\"', '68d75ea2000000001a00b44f', '0');
