INSERT INTO `xhs_note_comment` VALUES (2981, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087820397, 1781087820397, '6938ea08000000001d027a00', 1765337608000, '68ca7a060000000012017da4', '是啊，一方面觉得学钢琴就是在烧钱。一方面又深刻体会到，确实可以开发大脑，孩子现在初一，重点校，集团校初一年级4870人，娃考到了年级32名。这么一看，也不白花那么多钱！', 0, '\"\"', '69387c4f0000000038004d2e', '3');
INSERT INTO `xhs_note_comment` VALUES (2982, '611e1b53000000000100744a', '葡萄干麻麻', 'https://sns-avatar-qc.xhscdn.com/avatar/61691268202bbcfa90d2d018.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087820439, 1781087820439, '699a48fc0000000009037be8', 1771718909000, '68ca7a060000000012017da4', '电钢练习可以考级么？', 0, '\"\"', '68ce68ee0000000030011789', '0');
INSERT INTO `xhs_note_comment` VALUES (2983, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087820474, 1781087820474, '699beb310000000006031491', 1771825970000, '68ca7a060000000012017da4', '做练习的时候临时用可以，因为钢琴有重锤，按键需要力气，演奏时候必须有“强弱效果”才能有表现效果，钢琴考级除了要求弹奏顺畅更需要演奏出感情来。就我家娃的经验，如果钢琴考级一直用电钢练习，大概率考不过。但是如果电子琴考级，就肯定能用电钢练习。', 0, '\"\"', '699a48fc0000000009037be8', '1');
INSERT INTO `xhs_note_comment` VALUES (2984, '611e1b53000000000100744a', '葡萄干麻麻', 'https://sns-avatar-qc.xhscdn.com/avatar/61691268202bbcfa90d2d018.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087820505, 1781087820505, '699c723f000000001500f41f', 1771860544000, '68ca7a060000000012017da4', '电钢不是也有重锤吗', 0, '\"\"', '699beb310000000006031491', '0');
INSERT INTO `xhs_note_comment` VALUES (2985, '5f13dd15000000000100156f', '是奇迹呀', 'https://sns-avatar-qc.xhscdn.com/avatar/643595b9b1e3c7ad3b2fd700.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087820540, 1781087820540, '699ed8eb000000001500c62d', 1772017899000, '68ca7a060000000012017da4', '就是想问下您们学校有延时课吗，几点放学啊，我感觉每天练2小时，学习一点也搞不了了[捂脸R]', 0, '\"\"', '68ce68ee0000000030011789', '0');
INSERT INTO `xhs_note_comment` VALUES (2986, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087823297, 1781087823297, '69a0e3310000000006009858', 1772151602000, '68ca7a060000000012017da4', '电钢的重锤和钢琴的重锤完全不一样，百度查下！孩子弹琴时候，两者需要的力度也不一样。', 0, '\"\"', '699c723f000000001500f41f', '0');
INSERT INTO `xhs_note_comment` VALUES (2987, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087823338, 1781087823338, '69a0e35c00000000050301ae', 1772151645000, '68ca7a060000000012017da4', '课后延时到晚上6点半，成绩年级前5，一点儿不耽误学习！', 0, '\"\"', '699ed8eb000000001500c62d', '0');
INSERT INTO `xhs_note_comment` VALUES (2988, '5f13dd15000000000100156f', '是奇迹呀', 'https://sns-avatar-qc.xhscdn.com/avatar/643595b9b1e3c7ad3b2fd700.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087823373, 1781087823373, '69a10f99000000001101a0af', 1772162970000, '68ca7a060000000012017da4', '怎么安排的呀[失望R]9点能睡吗，能运动吗', 0, '\"\"', '69a0e35c00000000050301ae', '0');
INSERT INTO `xhs_note_comment` VALUES (2989, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087823404, 1781087823404, '69a4f9ed000000000600c5f7', 1772419565000, '68ca7a060000000012017da4', '9点肯定是不能睡呀，大约11点半睡！', 0, '\"\"', '69a10f99000000001101a0af', '0');
INSERT INTO `xhs_note_comment` VALUES (2990, '60d65318000000000101f66c', '岁月静好', 'https://sns-avatar-qc.xhscdn.com/avatar/c94b2589011be6d87bfbbbf21db9e2a0.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087823440, 1781087823440, '69a4fa26000000000600d2f7', 1772419623000, '68ca7a060000000012017da4', '每天早晨学校有晨跑30分钟，周末有体能班2小时。', 0, '\"\"', '69a10f99000000001101a0af', '0');
INSERT INTO `xhs_note_comment` VALUES (2991, '670c9004000000001d020053', '邱菊', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f83b46568f580649586.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087825995, 1781087825995, '69b8e4ef0000000016016041', 1773724912000, '68ca7a060000000012017da4', '你们那边没那么卷，我们这边每天练琴二小时，文化课基本就废了，作业都做不到这么完，除非是很有天赋，打算以后去走专业路线', 0, '\"\"', '69a4fa26000000000600d2f7', '0');
INSERT INTO `xhs_note_comment` VALUES (2992, '6249d73f0000000010004445', '望人在天北', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31urscevi2q005oi9qsvk0h25jj9mjmg?imageView2/2/w/120/format/jpg', '北京', 1781087826045, 1781087826045, '6a1f086300000000290359dc', 1780418660000, '68ca7a060000000012017da4', '哪有....我14年考过的十级，当时还有一年中考，每天从八点练到晚上十二点，四个小时 练半年啃下来了，那会音协还要求配一个乐理三级，暑假天天在练琴 乐理 补文化课之间连轴转，最后考上了全省第一的高中，现在是985理科硕士，练琴的时间规划好了对学习影响不大的', 0, '\"\"', '69b8e4ef0000000016016041', '0');
INSERT INTO `xhs_note_comment` VALUES (2993, '5887648882ec3951437a503a', 'momo66', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31dr9l9ttgu0g492oc2i8gk1q4dia2f0?imageView2/2/w/120/format/jpg', NULL, 1781087828092, 1781087828092, '68ce04f10000000002017bf4', 1758332145000, '68ca7a060000000012017da4', '请问学了多久？是电钢吗', 0, '\"\"', '68cbb0ab000000002301f4fd', '1');
INSERT INTO `xhs_note_comment` VALUES (2994, '5edc2db4000000000100033f', '我就是那个压舱石', 'https://sns-avatar-qc.xhscdn.com/avatar/63d5167672e641d79eaaf43c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087829033, 1781087829033, '68ce05c30000000030011e61', 1758332356000, '68ca7a060000000012017da4', '电钢，才开始学，太难了，感觉没啥天赋，目标是3级', 0, '\"\"', '68ce04f10000000002017bf4', '1');
INSERT INTO `xhs_note_comment` VALUES (2995, '5887648882ec3951437a503a', 'momo66', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31dr9l9ttgu0g492oc2i8gk1q4dia2f0?imageView2/2/w/120/format/jpg', NULL, 1781087829083, 1781087829083, '68ce1ef0000000000b01d313', 1758338801000, '68ca7a060000000012017da4', '自学还是跟老师呀？我也没啥要求，要是能会看简谱。 加上会配左手就好了。我连钢琴还没买', 0, '\"\"', '68ce05c30000000030011e61', '2');
INSERT INTO `xhs_note_comment` VALUES (2996, '5edc2db4000000000100033f', '我就是那个压舱石', 'https://sns-avatar-qc.xhscdn.com/avatar/63d5167672e641d79eaaf43c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087829118, 1781087829118, '68ce2298000000003000941a', 1758339737000, '68ca7a060000000012017da4', '请了一对一的老师，用的是五线谱', 0, '\"\"', '68ce1ef0000000000b01d313', '1');
INSERT INTO `xhs_note_comment` VALUES (2997, '6082f23a000000000101d222', '魔法酥', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31h7m6c8n3a005o42u8t0bkh20ifrdio?imageView2/2/w/120/format/jpg', NULL, 1781087829155, 1781087829155, '68ce9fcb00000000300113ca', 1758371787000, '68ca7a060000000012017da4', '三级很简单很简单，目标定高一点[派对R]', 0, '\"\"', '68cbb0ab000000002301f4fd', '1');
INSERT INTO `xhs_note_comment` VALUES (2998, '5edc2db4000000000100033f', '我就是那个压舱石', 'https://sns-avatar-qc.xhscdn.com/avatar/63d5167672e641d79eaaf43c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087829189, 1781087829189, '68cea0800000000030010877', 1758371968000, '68ca7a060000000012017da4', '考完3级，那就再定个5级，得能达到才行，我现在才1级，手都合抽筋了', 0, '\"\"', '68ce9fcb00000000300113ca', '4');
INSERT INTO `xhs_note_comment` VALUES (2999, '5f41e1090000000001008597', '轩尼诗XO', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30up6do6nli6g5nq1s44g91cn7kigjsg?imageView2/2/w/120/format/jpg', NULL, 1781087831713, 1781087831714, '68d00e8f0000000030009784', 1758465680000, '68ca7a060000000012017da4', '我也是线下学了一年半了，我喜欢练琴', 0, '\"\"', '68ce2298000000003000941a', '0');
