INSERT INTO `xhs_note_comment` VALUES (3017, '656e7f50000000002002f9a1', '柔姐', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31uiubu2j1m6g5pbeft885ud1fvfdbq8?imageView2/2/w/120/format/jpg', NULL, 1781087841834, 1781087841834, '68cfc47f00000000300171fb', 1758446719000, '68ca7a060000000012017da4', '7、8级这样吧', 0, '\"\"', '68cec9c60000000001001e42', '3');
INSERT INTO `xhs_note_comment` VALUES (3018, '633789ac000000001901cc77', 'Mousse.🍊', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v3t7tcfjq005opnh6m6bj3nmfs15d8?imageView2/2/w/120/format/jpg', NULL, 1781087842472, 1781087842472, '68d1ce7a000000003001f486', 1758580347000, '68ca7a060000000012017da4', '7级往上吧，这个主要是锻炼视奏能力，我考完七级就是不学了，多弹几遍可以勉强能听', 0, '\"\"', '68cec9c60000000001001e42', '1');
INSERT INTO `xhs_note_comment` VALUES (3019, '661e7b820000000003030c2c', '北北XIXI', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31cr02nod0k6g5pgufe10u31co9ppr60?imageView2/2/w/120/format/jpg', NULL, 1781087842515, 1781087842515, '68d37a8f00000000300205c5', 1758689936000, '68ca7a060000000012017da4', '真的吗？我儿子学了几个月，我让开始在家弹流行曲，在琴房按课程走。。半年多就能弹流行曲了。。现在是一首曲子弹个一两小时就会了，当然弹的肯定有瑕疵，或者有不少细节问题。。', 0, '\"\"', '68cfc47f00000000300171fb', '0');
INSERT INTO `xhs_note_comment` VALUES (3020, '656e7f50000000002002f9a1', '柔姐', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31uiubu2j1m6g5pbeft885ud1fvfdbq8?imageView2/2/w/120/format/jpg', NULL, 1781087842548, 1781087842548, '68d37e9e000000003000b4be', 1758690974000, '68ca7a060000000012017da4', '如果你按正常流程学的话就是这样啊，你专门练流行的话就是像你儿子这样', 0, '\"\"', '68d37a8f00000000300205c5', '0');
