INSERT INTO `xhs_note_comment` VALUES (3026, '62614ef40000000010006455', '北京雅马哈钢琴总部旗舰', 'https://sns-avatar-qc.xhscdn.com/avatar/626154d8d3d679bbece4d289.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087936861, 1781088903725, '67ec7a3c000000001e00f70d', 1743551036000, '67ebb714000000001c02fe0d', '可以在雅马哈电子键盘里，查看这个琴的功能介绍，我们做了20个小视频。每个功能都有非常详细的讲解，帮助顾客更好的使用CLP885[飞吻R]', 1, '\"\"', '0', '4');
INSERT INTO `xhs_note_comment` VALUES (3027, '5b0916ae4eacab60be7041ad', '等待背离', 'https://sns-avatar-qc.xhscdn.com/avatar/619f9aaca7a6c4b9c5bd2254.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087936899, 1781087936899, '67ecbaed0000000012000866', 1743567598000, '67ebb714000000001c02fe0d', '我前几年心情最差的时候，弹钢琴，弹着弹着心情就放松了', 1, '\"\"', '0', '0');
