INSERT INTO `xhs_note_comment` VALUES (3029, '55640c50a75c9502c19e6507', 'LX会等到天亮', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31sd916o5686g40mfvo650p87fh5mgp8?imageView2/2/w/120/format/jpg', NULL, 1781087936995, 1781088903903, '67ec9666000000001f0041c3', 1743558246000, '67ebb714000000001c02fe0d', '装修的时候同买了885，自从买完了只弹了四五个下午，就跟着公婆回他们老家过年，一呆就是小半年，之后还要回我自己老家待个把个月，想起家里的885买的时候还是刚上市不久，等能弹的时候就变成大半年的琴，就觉得心痛[哭惹R]不过好在我自己老家还有一台好几年前的535[笑哭R][笑哭R]比不上885但是起码能解解痒[笑哭R]', 3, '\"\"', '0', '2');
