INSERT INTO `xhs_note_comment` VALUES (3034, '5b1b75ed11be103fac98207c', '海姐姐', 'https://sns-avatar-qc.xhscdn.com/avatar/5b1b75ed11be103fac98207c.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087939704, 1781087939704, '67ec68f20000000012000c58', 1743546611000, '67ebb714000000001c02fe0d', '的确是  我开始就说买个p225吧  后来觉得说ydp145还是好点 好歹有个盖子  去店里看上了ydp165 到最后却买了xlp725  跨越了[偷笑R][偷笑R]', 0, '\"\"', '67ec0c9f000000002001799e', '3');
INSERT INTO `xhs_note_comment` VALUES (3035, '5dd71ac9000000000100aefa', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/cd255d0e201935e0d852bd371f18c198.jpg?imageView2/2/w/120/format/jpg', NULL, 1781087939749, 1781087939749, '67ec8515000000001e0388d1', 1743553814000, '67ebb714000000001c02fe0d', '我就不一样了 直接网上下单 不给自己这种机会[偷笑R] 后来去店里买真钢 也是预算范围内最热销的 试了一下直接付钱 快到销售也惊讶了一下 [笑哭R] 其实我就是是个不愿意说话的i人而已...', 0, '\"\"', '67ec0c9f000000002001799e', '3');
