INSERT INTO `xhs_note_comment` VALUES (3189, '5968a51650c4b40fe7a1794b', '长沙高级钢琴调音师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311qjguhv0mqg49m32jihcuab3u9g23g?imageView2/2/w/120/format/jpg', NULL, 1781088052529, 1781088052529, '660eafd70000000015003d2b', 1712238551000, '65f80f7e000000000d00c286', '如何通过外观分辨纽约和汉堡施坦威：相对老的纽约施坦威外观上和汉堡的有明显的区别，一般汉堡是亮面漆📀，纽约2012年之前是哑光。老款纽约施坦威侧面更有棱角，汉堡琴边角更圆润（19年开始统一外观，纽约款铸铁板会标注made in usa）', 0, '\"\"', '660eaf3f00000000150038e5', '4');
INSERT INTO `xhs_note_comment` VALUES (3190, '63ad59a20000000026010c78', '小红薯651A90CE', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31gkcb5ok3s3g5otdb6h9i33oqm9n250?imageView2/2/w/120/format/jpg', NULL, 1781088053625, 1781088053625, '660eb437000000001902c29b', 1712239671000, '65f80f7e000000000d00c286', '能私信你吗', 0, '\"\"', '660eafd70000000015003d2b', '0');
INSERT INTO `xhs_note_comment` VALUES (3191, '5968a51650c4b40fe7a1794b', '长沙高级钢琴调音师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311qjguhv0mqg49m32jihcuab3u9g23g?imageView2/2/w/120/format/jpg', NULL, 1781088053661, 1781088053661, '660f3565000000001503984d', 1712272741000, '65f80f7e000000000d00c286', '可以的', 0, '\"\"', '660eb437000000001902c29b', '0');
INSERT INTO `xhs_note_comment` VALUES (3192, '5968a51650c4b40fe7a1794b', '长沙高级钢琴调音师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311qjguhv0mqg49m32jihcuab3u9g23g?imageView2/2/w/120/format/jpg', NULL, 1781088055700, 1781088055700, '65fec5f7000000000b017c37', 1711195639000, '65f80f7e000000000d00c286', '1、业内普遍认为汉堡施坦威比纽约产的施坦威要好，纽约生产施坦威主要针对北美时长销售，我国销售的施坦威基本来自德国汉堡。美国市场上，德国产的施坦威比纽约产的施坦威贵至少5000。2、行业内部分人士及部分演奏家测评：a.纽约琴音色（重低音区低沉有厚度，适合印象派朦胧感，整体音量稍大）b.汉堡琴音色（中高音区清澈明亮、穿透感好、音色丰富，适合演奏李斯特贝多芬爆发力作品，但整体音量偏小）c.盲选倾向纽约琴：汉堡琴=4：6注：从核心设计上两地采用统一的音源，也就是发声体是一样的，共鸣效果是一样的。但是在其他材料（如榔头）和整音手法上稍有不同，2019年后斯坦威已经在统一标准。', 0, '\"\"', '65fe505a0000000016007b9b', '8');
