INSERT INTO `xhs_note_comment` VALUES (3324, '576d20617fc5b858ec8a045f', '一颗胖糖', 'https://sns-avatar-qc.xhscdn.com/avatar/576d20617fc5b858ec8a045f.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088430440, 1781088430440, '68a292080000000027004b24', 1755484681000, '68948c820000000023035cf2', '更新后续，师傅来调音了，说是没什么问题，如果连起来弹奏，就是正常声音。还有就是，我打400电话问过雅马哈售后了，他们售后都是经销商负责的，所以大家买雅马哈最好找靠谱的经销商。', 11, '\"\"', '0', '2979');
INSERT INTO `xhs_note_comment` VALUES (3325, '678a3487000000000e0138c5', 'momoMisha', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f6e338379fac1893093.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088430475, 1781088430475, '68a42b730000000026038971', 1755589491000, '68948c820000000023035cf2', '可以去医院检查一下耳朵，我是认真的，且没有阴阳怪气，且是真心的建议。失聪都是从高频开始，在哒哒哒的后面有很明显的钢琴声音，要不是搞抽象就去医院检查一下吧，毕竟学音乐的。', 303, '\"\"', '0', '1.2万');
INSERT INTO `xhs_note_comment` VALUES (3326, '5e021d26000000000100acf0', '面宝', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31r5ue8emga005ng23kj09b7gqs2nt0g?imageView2/2/w/120/format/jpg', NULL, 1781088430503, 1781088430503, '68a4c92900000000300242bc', 1755629866000, '68948c820000000023035cf2', '评论区的先别急，你们晚上玩手机肯定不敢把音量调高，你把音量稍微调高一点点凑到听筒听就能听到所有琴键声音了[完啦R][完啦R][完啦R]', 211, '\"\"', '0', '5359');
INSERT INTO `xhs_note_comment` VALUES (3327, '62ca72dc000000001501c65a', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo319c78udq6g6g5omaebe5bhiq5982jlo?imageView2/2/w/120/format/jpg', NULL, 1781088430533, 1781088430533, '68a4c826000000002700f22e', 1755629607000, '68948c820000000023035cf2', '我倒是都听到了，但是这个哒哒声怎么这么大，是节拍器还是按键敲的声音啊[黑薯问号R]', 34, '\"\"', '0', '7865');
