INSERT INTO `xhs_note_comment` VALUES (3359, '5c3a9df80000000006024f69', '24G网民', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31uld8qou2i705n1qjns1kjr94t40k7g?imageView2/2/w/120/format/jpg', NULL, 1781088589139, 1781088589139, '664f455b0000000008001adb', 1716471131000, '65a91962000000002b017796', '🆘今天开了电钢琴，琴键音量调的小，噪音听上去就这个效果，吓得我赶紧来小红书搜经验帖[喝奶茶R]', 3, '\"\"', '0', '7');
