INSERT INTO `xhs_note_comment` VALUES (3388, '5cb72210000000001603cdb8', 'CX330', 'https://sns-avatar-qc.xhscdn.com/avatar/631b20297ef7f24621620f76.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088702070, 1781088702070, '67e621890000000012012c84', 1743135113000, '67176cc80000000016020c42', '我想问问，我这种25岁了，只是喜欢弹琴的，不考级，手型估计也练不出来的，也不推荐折叠钢琴吗[失望R]', 1, '\"\"', '0', '0');
INSERT INTO `xhs_note_comment` VALUES (3389, '66b377e5000000001d030fb9', '惘叙祈', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31nb3mv1f5m605pljevine3tpt0i2rr0?imageView2/2/w/120/format/jpg', NULL, 1781088702132, 1781088702132, '67bb16a70000000019015c20', 1740314279000, '67176cc80000000016020c42', '家里不是很有钱，三百多的能好用吗，我现在零基础，不是专业要学的，就玩玩', 1, '\"\"', '0', '0');
