INSERT INTO `xhs_note_comment` VALUES (3391, '6277cac50000000021024170', '小白', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31o6b5oj3mg605ojnpb2ocgbgc46e940?imageView2/2/w/120/format/jpg', NULL, 1781088702245, 1781088702245, '699824e9000000000803260d', 1771578602000, '67176cc80000000016020c42', '预算有限，就几百块，想买个百元琴玩玩，3分钟热度就想试一下[doge]能买吗？有什么能稍微推荐一点的吗？', 1, '\"\"', '0', '1');
INSERT INTO `xhs_note_comment` VALUES (3392, '61498cc7000000000201cf83', '番茄火锅', 'https://sns-avatar-qc.xhscdn.com/avatar/63c15a8650f03d23daaadd5e.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088702282, 1781088702282, '678ac500000000002103f7c5', 1737147648000, '67176cc80000000016020c42', '我家有真钢，我就想买一个折叠琴过过手瘾，也方便晚上弹不吵到邻居，1000以内预算，推荐哪个', 3, '\"\"', '0', '1');
INSERT INTO `xhs_note_comment` VALUES (3393, '60836fbf000000000100b2a4', '邱邱Rin！', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3158rd8b1hc505o43duvg9cl4vpdpukg?imageView2/2/w/120/format/jpg', NULL, 1781088702313, 1781088702313, '674346f600000000070167ce', 1732462327000, '67176cc80000000016020c42', '各位弹“钢琴”的姐妹听句劝，电子琴真的难听且包破防的！众所周知钢琴大部分都是一只手主旋律，一只手伴奏，但是电子琴不能考手指力度调节声音强弱，然后你会听到伴奏像个机关枪在那里砸', 3, '\"http://sns-web-i10.rednotecdn.com/202606101851/a41da46f147041431e0540c74cdae78e/comment/1040g2h031ajbtl1dnc605o43duvg9cl4nb7ct9g!nd_whgt34_webp_wm_1?src=A\"', '0', '4');
INSERT INTO `xhs_note_comment` VALUES (3394, '65086dd10000000012005c05', 'ばか', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7ecfb46568f58064957a.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088702344, 1781088702344, '68c0424c000000003000ae5d', 1757430349000, '67176cc80000000016020c42', '如果艺考的话，追求真纲手感有没有什么比较推荐的？价格要合适一点，不用太贵的。', 1, '\"\"', '0', '0');
