INSERT INTO `xhs_note_comment` VALUES (3403, '5e6c27a80000000001000ba7', '拿尿滋你你会跑吗？', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31usa92eejq605njc4uk082t7vv3jgvg?imageView2/2/w/120/format/jpg', NULL, 1781088740817, 1781088740817, '69eebd16000000002b02b82e', 1777253655000, '69ed93e200000000350276e3', '我教你一个嘻嘻，你记住4152637，升号有几个就从左往右数几个，降号就从右往左数，比如你这个有6个降号，那么就会降736251这六个音', 64, '\"\"', '0', '682');
INSERT INTO `xhs_note_comment` VALUES (3404, '61892521000000001000be3b', 'Dr.916', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31mtascr34q005oc94kgk1fhr54krskg?imageView2/2/w/120/format/jpg', NULL, 1781088740859, 1781088740859, '69ef028200000000270293d8', 1777271426000, '69ed93e200000000350276e3', '多练就熟悉了。与其死记硬背，不如尝试理解背后的理论。你看，升号从左到右每个音都是往上五度（4152637），降号是相反往下五度（7362514）。第四升和降都是2（D）。通过这个你可以逐渐了解大小调的音程关系，这样你自己就能推出一个调有哪些升降号了。到了这一步你就会发现，还是死记硬背简单。[微笑R]', 16, '\"\"', '0', '428');
INSERT INTO `xhs_note_comment` VALUES (3405, '655803ec00000000020357f1', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31i50gnf27e005pao0fm0mlvh349426o?imageView2/2/w/120/format/jpg', NULL, 1781088740887, 1781088740887, '69f6a4be0000000029034ef6', 1777771710000, '69ed93e200000000350276e3', '图一这个实际上是最简单好记的，因为降号太多，你只需要记fa是不用降的，其余所有音都要弹降的就行了', 7, '\"\"', '0', '42');
INSERT INTO `xhs_note_comment` VALUES (3406, '5b9fac22281c9a0001872a2e', 'Susan', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30rhcg1hhhe004b1fchm24ahek04lgd0?imageView2/2/w/120/format/jpg', NULL, 1781088740914, 1781088740914, '69ed9721000000002702943b', 1777178402000, '69ed93e200000000350276e3', '降号多的就看不用降的音就好了。然后还有就是可以花些时间去把所有大小调音阶弹熟，会有些帮助。', 8, '\"\"', '0', '41');
INSERT INTO `xhs_note_comment` VALUES (3407, '5e5eec730000000001008e86', '英皇钢琴乐理双语教学Sophia老师🎹', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31kk08cplj06g5niuthpg93k6bumag5o?imageView2/2/w/120/format/jpg', NULL, 1781088740940, 1781088740940, '69ed98c80000000028035387', 1777178825000, '69ed93e200000000350276e3', '主要是不在于看谱子上写了几个降号,是在于听觉上你有没有建立一定的调性感，调性的位置感，每个音对于主音的关系，每个音对于主音的方向感，导向主音的还是远离主音。', 5, '\"\"', '0', '9');
INSERT INTO `xhs_note_comment` VALUES (3408, '5547ff0fb203d91ed3008c03', 'applepie丿', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3202fhspo3q0040i2mhvgv303p6k13to?imageView2/2/w/120/format/jpg', NULL, 1781088740967, 1781088740967, '69f2bd7b0000000029019bda', 1777515899000, '69ed93e200000000350276e3', '肥貓下樓吃早餐 Fat cat go down and eat breakfast FCGDAEB 升調 降調就是反過來用[笑哭R]', 5, '\"\"', '0', '48');
INSERT INTO `xhs_note_comment` VALUES (3409, '65388603000000000400a2c0', '🎹青言琴语', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v7qnaqgii105p9ogo1h18m0ump2sag?imageView2/2/w/120/format/jpg', NULL, 1781088740992, 1781088740992, '69edb4b50000000029010049', 1777185974000, '69ed93e200000000350276e3', '音阶和弦琶音多练一练尤其是你弹的那首曲子的调要熟练，效率会明显提升o[派对R]', 1, '\"\"', '0', '2');
