INSERT INTO `xhs_note_comment` VALUES (3451, '61a261100000000021028476', '拍你的兔头💙', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30vfvu76olo005od2c488d13m095lck8?imageView2/2/w/120/format/jpg', NULL, 1781088903754, 1781088903754, '684eb5760000000020023219', 1749988726000, '67ebb714000000001c02fe0d', '想问下猫会抓电钢的腿吗[笑哭R]原来我那个位置放的桌子 桌腿是可以磨爪子的[笑哭R]', 2, '\"\"', '0', '0');
