INSERT INTO `xhs_note_comment` VALUES (3453, '5cc78e5f0000000010024914', '喵喵喵喵喵', 'https://sns-avatar-qc.xhscdn.com/avatar/630556dcd5b18b001cf0ed15.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088903822, 1781088903822, '67eca467000000001f009548', 1743561831000, '67ebb714000000001c02fe0d', '我也是零基础，两礼拜前心血来潮想学，立马下单了琴行二手，每天我女儿睡着以后练一小时，刚学完小汤一', 4, '\"\"', '0', '4');
