INSERT INTO `xhs_note_comment` VALUES (3459, '55a8c4e5c2bdeb6c78166f92', '柠檬momo', 'https://sns-avatar-qc.xhscdn.com/avatar/64b14d93732bf352275e7031.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088958025, 1781088958025, '687861290000000011019a98', 1752719657000, '687480bd000000001d00e6d7', '原来不是琴的问题，是人的问题，只要弹的好，2千的也好听[偷笑R]', 1, '\"\"', '0', '143');
