INSERT INTO `xhs_note_comment` VALUES (3465, '54e4b9332e1d932d04c09e3d', '梦嫕✨✨', 'https://sns-avatar-qc.xhscdn.com/avatar/641127856f09d51f9d06770f.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088958226, 1781088958226, '6975fbd80000000018039164', 1769339864000, '687480bd000000001d00e6d7', '小朋友初学买145还是165合适呀', 2, '\"\"', '0', '0');
