INSERT INTO `xhs_note_comment` VALUES (3468, '645f6405000000001400cce7', '王南煦', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31vomabkcig5g5p2vcg2l1j7788ukll0?imageView2/2/w/120/format/jpg', NULL, 1781088960337, 1781088960337, '6896169000000000290267ac', 1754666640000, '687480bd000000001d00e6d7', '因为电钢琴随时都可以弹不用考虑扰民，也不用一直调音', 0, '\"\"', '6891508c000000002a018a05', '61');
