INSERT INTO `xhs_note_comment` VALUES (3470, '5e1f1e71000000000100bf4a', '甚是想念', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31ihp4v1ng8605ngv3pog9fqafm7nboo?imageView2/2/w/120/format/jpg', NULL, 1781088967098, 1781088967098, '68e34db90000000033021134', 1759727033000, '687480bd000000001d00e6d7', '一般都是买几个踏板呢[偷笑R]', 0, '\"\"', '68affec00000000030010728', '0');
INSERT INTO `xhs_note_comment` VALUES (3471, '68425a11000000001a03a6b5', '杭州买房小胖', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31k0f7h8d32005q22b88mn9ll79vidvg?imageView2/2/w/120/format/jpg', NULL, 1781088970970, 1781088970970, '6965108b000000000f00f1fc', 1768231051000, '687480bd000000001d00e6d7', '是的，我也这么觉得，前面的钢琴因为弹奏者能力强，听着都很好听，差别不大，一到885，那声音确实不一样了', 0, '\"\"', '694d94e30000000016021ce8', '7');
INSERT INTO `xhs_note_comment` VALUES (3472, '5c6a61540000000012034ae7', '阿静1', 'https://sns-avatar-qc.xhscdn.com/avatar/6066d9dc3bcb1c95f4414667.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088974534, 1781088974534, '697b3dc0000000000f025acc', 1769684417000, '687480bd000000001d00e6d7', '建议145喔', 0, '\"\"', '6975fbd80000000018039164', '0');
INSERT INTO `xhs_note_comment` VALUES (3473, '63e9c00e000000002601077c', '烟云旦晚', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30uq01d9ulg605ov9o079i1rs8pm9dp8?imageView2/2/w/120/format/jpg', NULL, 1781088977816, 1781088977816, '687bb68a0000000015001fd5', 1752938122000, '687480bd000000001d00e6d7', '我说怎么这么眼熟[doge]', 0, '\"\"', '6877d8cf0000000009017df7', '0');
INSERT INTO `xhs_note_comment` VALUES (3474, '67809dd10000000006013b8f', 'HugeWhale', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31q90hvvmga5g5ps0jn8hiesf95fddh8?imageView2/2/w/120/format/jpg', NULL, 1781088983875, 1781088983875, '6a012c14000000002902c1da', 1778461717000, '69fe9a800000000020039761', '因为只想弹流行，对古典没兴趣；不需要调音省事省钱；不扰民晚上可以插耳机弹；可以直接连接蓝牙学习，智能方便；人爱好音乐的拿个计算器都能弹，音乐没有高低贵贱之分，那些走专业路子弹真钢的，没人跟你们抢饭碗，无需贬低那些刚入门的对钢琴好奇的小白；钢琴没有那么高贵，以前可能只是高考加分项或者少数人才能拥有的，现在能人人都可以弹了不是好事嘛[doge]', 17, '\"\"', '0', '1565');
INSERT INTO `xhs_note_comment` VALUES (3475, '5c8de7330000000011007ae1', '橡木音乐', 'https://sns-avatar-qc.xhscdn.com/avatar/seller_69e62b895b61c10001850bc0?imageView2/2/w/120/format/jpg', NULL, 1781088983915, 1781088983915, '69ff29ae000000002803a3eb', 1778330031000, '69fe9a800000000020039761', '我专业的，也用电钢，因为晚上能弹[doge]买个大牌木质键盘电钢都解决了。我朋友是茱莉亚的老师，她买了一个十几万的数码钢琴', 79, '\"\"', '0', '190');
INSERT INTO `xhs_note_comment` VALUES (3476, '6200ea60000000001000a908', '老马', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311q3tkav0o5g5og0t9g41a88e2v7ok8?imageView2/2/w/120/format/jpg', NULL, 1781088983945, 1781088983945, '69ffc4130000000028034f6d', 1778369555000, '69fe9a800000000020039761', '两种钢琴手感差很多啊，真钢可以通过手指的轻重缓急来控制音量音质，电钢做不到，电钢唯一的好处就是不扰民。', 21, '\"\"', '0', '46');
INSERT INTO `xhs_note_comment` VALUES (3477, '5a8795104eacab3ec2122c91', '宇宙💐宇宙💐', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31vg2n508jm5g4a1gl3ah0b4hq5p5dig?imageView2/2/w/120/format/jpg', NULL, 1781088983973, 1781088983973, '69fff793000000002800a14d', 1778382739000, '69fe9a800000000020039761', '很多人肯定小时候学琴用的真钢，长大了自己住，只是为了维持练琴或者拍拍视频的话，买个电钢完全足够了。反正我自己就是，我又不做什么演奏家，也不用多专业，只想维持自己练琴的频率，自己租房也不方便做什么隔音措施，买个电钢连着耳机方便练琴就是。', 6, '\"\"', '0', '67');
INSERT INTO `xhs_note_comment` VALUES (3478, '6306b9750000000012000a64', '车展拍摄工具人', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo318vebmtt0m605oo6n5qkg2j47sdlvqo?imageView2/2/w/120/format/jpg', NULL, 1781088983998, 1781088983998, '69ff1fc3000000002702f954', 1778327492000, '69fe9a800000000020039761', '常年在四级六级徘徊的，几千块的电钢弹弹得了。没钱买三角钢琴的，电钢弹弹得了。你要是水平到了，自然有人请你弹三角真钢，还给你钱呐', 3, '\"\"', '0', '33');
INSERT INTO `xhs_note_comment` VALUES (3479, '5f7de6750000000001002357', 'Iris🎋', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31n44cgkemm0g5nrtspqg88qn1s6vp2o?imageView2/2/w/120/format/jpg', NULL, 1781088984030, 1781088984030, '69ff3231000000002803188a', 1778332209000, '69fe9a800000000020039761', '南方不推薦用真鋼，我家用真鋼，太容易受潮了，很難保養[捂脸R]', 4, '\"\"', '0', '24');
INSERT INTO `xhs_note_comment` VALUES (3480, '63d35eb70000000026005580', 'Zimer-Young', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30ucvfuh1565g5oujbqrpglc03l2310g?imageView2/2/w/120/format/jpg', NULL, 1781088984059, 1781088984059, '69feeaa9000000002b027322', 1778313897000, '69fe9a800000000020039761', '1.真钢用久了会走音要调律成本；电钢不用调律插电就能用\n2.真钢是机械成声受环境影响大，发平台推流得用专业录音设备减小环境影响；电钢可以直接机录，发平台直接导入音轨就完事\n3.真钢真实触键反馈，需要练习时间成本，不然某些音容易弹虚、糊；电钢midi成声，无论细软塌的面条手、还是紧绷的僵尸手、甚至一屁股坐上去，都能弹出\"美妙的\"音色，堪称技术遮羞布，练习成本较低，能读谱就行', 3, '\"\"', '0', '69');
INSERT INTO `xhs_note_comment` VALUES (3481, '5e3d8048000000000100454d', '公孙清墨', 'https://sns-avatar-qc.xhscdn.com/avatar/5e3d8048000000000100454d.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088984091, 1781088984091, '69ff2a3c00000000270223d5', 1778330172000, '69fe9a800000000020039761', '主要是不扰民！成人没事儿谈谈流行音乐电钢是最好的！不扰民是关键！有钱买单独别墅的才多少人？大部分人住的楼房都有邻居，你想弹邻居不想听怎么办？总不能出门被骂死……所以还是电钢自己戴耳机吧。', 2, '\"\"', '0', '25');
INSERT INTO `xhs_note_comment` VALUES (3482, '5a930f184eacab110335dac8', '粉粉酱', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7e90e29f7d0acadad8aa.jpg?imageView2/2/w/120/format/jpg', NULL, 1781088986131, 1781088986131, '6a0131f10000000028008152', 1778463218000, '69fe9a800000000020039761', '成年爱好者就没考虑过真钢，电钢深夜插耳机弹琴简直太爽了', 0, '\"\"', '6a012c14000000002902c1da', '523');
INSERT INTO `xhs_note_comment` VALUES (3483, '5a6849da11be10681b636d67', 'PRAIRIE SCAVENGER', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31fbvbek574004a12264tkrb7l67blf8?imageView2/2/w/120/format/jpg', NULL, 1781088989429, 1781088989429, '69ff2e46000000002b00019e', 1778331207000, '69fe9a800000000020039761', '前辈，能给推荐几款家用的电钢吗', 0, '\"\"', '69ff29ae000000002803a3eb', '10');
INSERT INTO `xhs_note_comment` VALUES (3484, '6710a687000000001d020edc', '小红薯6711FE9E', 'https://sns-avatar-qc.xhscdn.com/avatar/645b800677c97ef1a2abc7e0.jpg?imageView2/2/w/120/format/jpg', '内蒙古', 1781088992707, 1781088992707, '6a101e08000000002702f00b', 1779441161000, '69fe9a800000000020039761', '汗，力度键是入流数码钢琴的最基本功能。', 0, '\"\"', '69ffc4130000000028034f6d', '108');
