INSERT INTO `xhs_note_comment` VALUES (3506, '6613cb20000000000d024791', '䒛㾇🍥', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31tvsck43ne6g5pgjpcg3chshbher2s0?imageView2/2/w/120/format/jpg', NULL, 1781089063512, 1781089063512, '6795d61f000000000c010d76', 1737872929000, '65d44a1c0000000007005033', '所有琴键没声音怎么办', 9, '\"http://sns-web-i10.rednotecdn.com/202606101857/ae59fb8e1fd0b94a7762575664ecfc74/comment/1040g2h031d3v3daigm605pgjpcg3chshbb7r5jg!nd_whgt34_webp_wm_1?src=A\"', '0', '4');
