INSERT INTO `xhs_note_comment` VALUES (3508, '65c2f1b2000000001101b64e', 'Yami', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo310fmikspme605pe2u6p4bdie83jsdmg?imageView2/2/w/120/format/jpg', NULL, 1781089063577, 1781089063577, '66d7e0e900000000200243b0', 1725423850000, '65d44a1c0000000007005033', '我的电子琴有时候所有4/7健没有声音，最近是一直没声音，前几天拿去修理店又有声音了，维修师傅也没办法', 8, '\"\"', '0', '5');
INSERT INTO `xhs_note_comment` VALUES (3509, '60f8bfdc000000000101f24d', '隶书每日忘练', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31di8s92o125g5o7onve0bsid46d8nso?imageView2/2/w/120/format/jpg', NULL, 1781089063606, 1781089063606, '665fae070000000005026087', 1717546503000, '65d44a1c0000000007005033', '我的p85能开机但没有声音的，也想修一下，能说说需要注意什么吗？', 1, '\"\"', '0', '2');
INSERT INTO `xhs_note_comment` VALUES (3510, '5c08e1d4000000000500017c', 'Jenny🌸', 'https://sns-avatar-qc.xhscdn.com/avatar/5ea82910c8596b000171473f.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089063638, 1781089063638, '68cbfdbe00000000300056ba', 1758199232000, '65d44a1c0000000007005033', '我们家的开关打开灯亮，但按所有的键都没声音，是什么情况呀？', 1, '\"http://sns-web-i10.rednotecdn.com/202606101857/3595acdc5c9419e1ef1f2167a34a5be6/comment/1040g2h031misv1c1ks004busaigt80bsjja73mo!nd_whgt34_webp_wm_1?src=A\"', '0', '1');
INSERT INTO `xhs_note_comment` VALUES (3511, '5a51e4ef4eacab78eac54f05', '兰匠', 'https://sns-avatar-qc.xhscdn.com/avatar/5ebf939919448b00017ac5b3.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089063668, 1781089063668, '68d2154600000000300216e8', 1758598471000, '65d44a1c0000000007005033', '电源灯能亮但按键不响', 1, '\"\"', '0', '2');
INSERT INTO `xhs_note_comment` VALUES (3512, '5659aa9082718c2652bd4922', '田老师(武汉电钢琴维修师)', 'https://sns-avatar-qc.xhscdn.com/avatar/5659aa9082718c2652bd4922.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089063695, 1781089063695, '682c1703000000001c02d63b', 1747719939000, '65d44a1c0000000007005033', '电钢琴各个品牌型号键盘有差异，维修方法都不一样，单音不响可多是导电胶，但有七、八连续音不响多是键盘电路板问题', 1, '\"\"', '0', '4');
INSERT INTO `xhs_note_comment` VALUES (3513, '620af3320000000002020aec', 'Dreamer刘', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31a5ocji27e005ogaucp0k2nc5fk6428?imageView2/2/w/120/format/jpg', NULL, 1781089063727, 1781089063727, '67962ca8000000001a03a59e', 1737895081000, '65d44a1c0000000007005033', '螺丝全拆了，按键拆了，导电胶也用酒精擦洗了，接触面也擦洗了，插电试了，两个琴键还是没声音。放弃了，重新装回[笑哭R]', 1, '\"\"', '0', '1');
INSERT INTO `xhs_note_comment` VALUES (3514, '627e0c0d000000002102bf58', '小溪', 'https://sns-avatar-qc.xhscdn.com/avatar/627e0c0d000000002102bf58.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089065763, 1781089065763, '685024510000000020013a8f', 1750082642000, '65d44a1c0000000007005033', '修好了吗？通电情况下，我们也是所有琴键都没声音。', 0, '\"\"', '6795d61f000000000c010d76', '3');
INSERT INTO `xhs_note_comment` VALUES (3515, '5af68abde8ac2b4f65980e0f', '李开箱', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bfj9rvg0s604a58oj5bq3gfr00j850?imageView2/2/w/120/format/jpg', NULL, 1781089069144, 1781089069144, '66ab8cee000000001c03f5a6', 1722518766000, '65d44a1c0000000007005033', '琴键有些好拆有些不好拆，从某个角度来看，琴键好拆的话代表琴好拆好修，不好拆的话，默认让你别自己拆[笑哭R]', 0, '\"\"', '66ab5fc1000000001500a938', '4');
INSERT INTO `xhs_note_comment` VALUES (3516, '5ba5aa176b58b77856cf73e8', '想想真好', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31atbrjv8ni6g4b3p3cl1esv80b1ijf8?imageView2/2/w/120/format/jpg', NULL, 1781089072571, 1781089072571, '6700c6bf000000000f00ebdd', 1728104128000, '65d44a1c0000000007005033', '维修要多少钱啊', 0, '\"\"', '66d7e0e900000000200243b0', '0');
