INSERT INTO `xhs_note_comment` VALUES (3520, '5daeebbc0000000001009237', '天天快乐', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3122vg9mc3s105ndeteu094hntgh8hv8?imageView2/2/w/120/format/jpg', NULL, 1781089076129, 1781089076129, '68b1b8b600000000300327c8', 1756477623000, '65d44a1c0000000007005033', '几年没有用，今天通电全部不响了，这样修一下得多少钱？', 0, '\"\"', '682c1703000000001c02d63b', '1');
