INSERT INTO `xhs_note_comment` VALUES (3563, '61f7938c0000000021025876', '嘿哈猫', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31775l8s5jq6g5ofnie68cm3miub6rs8?imageView2/2/w/120/format/jpg', NULL, 1781089302958, 1781089302958, '6759ca8300000000110195aa', 1733937796000, '675113090000000007027455', '加油练琴！西蒙讲得真的很好，我也看了，回头我要支持他的讲义，希望这么优秀的老师能赚到钱~', 18, '\"\"', '0', '54');
INSERT INTO `xhs_note_comment` VALUES (3564, '548631dcd6e4a952f9c333c4', '大脸猫爱吃鱼', 'https://sns-avatar-qc.xhscdn.com/avatar/6412a7bd0e6651da59649a53.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089302994, 1781089302994, '67525499000000000d002883', 1733448858000, '675113090000000007027455', '同30+学琴，每天晚上下班回家刷抖音的时间全都用来练琴了，虽然进步缓慢，但是很有满足感[害羞R]', 7, '\"\"', '0', '48');
INSERT INTO `xhs_note_comment` VALUES (3565, '6255621c0000000021025764', 'Un Sospiro', 'https://sns-avatar-qc.xhscdn.com/avatar/661e4e2851459fd1a07963b1.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089303020, 1781089303020, '676bffe9000000001003fdde', 1735131113000, '675113090000000007027455', '赞！推荐一本关于音乐和钢琴的新书小说《流光与叹息》，目前位居当当网中国当代小说好评榜前五，目前豆瓣评分9.0+。这是一部以音乐为线索的长篇小说，讲述了一个钢琴家和作曲家的故事，也一个关于成长与探索、挣扎与自由的故事，对方方面面的话题做了深度思考，包括生活、社会、艺术、音乐、爱情等。其中所塑造的独特而闪闪发光的女性形象尤为令人印象深刻。贯穿全书的音乐（包括李斯特、瓦格纳、肖邦、贝多芬、德彪西等等），推动着故事情节的发展，文学和音乐的结合极具特色。很适合喜欢音乐的朋友读哦~', 3, '\"\"', '0', '37');
INSERT INTO `xhs_note_comment` VALUES (3566, '61c127b80000000010007397', '飞剑不动', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311v1nhrt1o005oe14us40ssn07o6po8?imageView2/2/w/120/format/jpg', NULL, 1781089303051, 1781089303051, '675113bf000000001a019a82', 1733366719000, '675113090000000007027455', '自学视频在哪个网站找到的', 5, '\"\"', '0', '0');
