INSERT INTO `xhs_note_comment` VALUES (3574, '57bc61bc6a6a69730797f6b2', 'BlueBlue', 'https://sns-avatar-qc.xhscdn.com/avatar/57bc61bc6a6a69730797f6b2.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089315340, 1781089315340, '675114bc000000001b0003a3', 1733366972000, '675113090000000007027455', '小红书，YouTube，抖音都有～搜搜关键字就好。乐理的话可以搜 三分钟音乐社，我还买了本成人自学钢琴的书，从坐姿手型五线谱那些学起[笑哭R]好多好多资源', 0, '\"\"', '675113bf000000001a019a82', '7');
INSERT INTO `xhs_note_comment` VALUES (3575, '57bc61bc6a6a69730797f6b2', 'BlueBlue', 'https://sns-avatar-qc.xhscdn.com/avatar/57bc61bc6a6a69730797f6b2.jpg?imageView2/2/w/120/format/jpg', NULL, 1781089318894, 1781089318894, '67534098000000001a025a55', 1733509272000, '675113090000000007027455', '国内不了解行情，看网上是1.2W左右。有时候可能打折，可以对比当地实体店和网上，考虑售后维修也比较重要。', 0, '\"\"', '6752d65c000000001a01a1b3', '0');
